// src/router.tsx

export function createRouter() {
  // loader 클라이언트 또는 유사한 데이터 저장소는 반드시
  // `createRouter` 함수 내부에서 만들어야 해요. 이렇게 하면
  // 데이터 저장소가 각 요청마다 고유하고 서버와 클라이언트
  // 모두에서 항상 존재하는 것이 보장돼요.
  const queryClient = new QueryClient()

  return createRouter({
    routeTree,
    // 편의를 위해 선택적으로 loaderClient를 router context에 제공해요
    // (router context에 원하는 어떤 것이든 제공할 수 있어요!)
    context: {
      queryClient,
    },
    // 서버에서 loader 클라이언트를 dehydrate해서 라우터가
    // 직렬화하고 클라이언트로 보낼 수 있게 해요
    dehydrate: () => {
      return {
        queryClientState: dehydrate(queryClient),
      }
    },
    // 클라이언트에서 서버에서 dehydrate한 데이터로
    // loader 클라이언트를 hydrate해요
    hydrate: (dehydrated) => {
      hydrate(queryClient, dehydrated.queryClientState)
    },
    // 선택적으로 `Wrap`을 사용해 router를 loader 클라이언트 provider로 감쌀 수 있어요
    Wrap: ({ children }) => {
      return (
        <QueryClientProvider client={queryClient}>
          {children}
        </QueryClientProvider>
      )
    },
  })
}

